import React, { useEffect, useState, useRef } from 'react';

const DemoNBack = ({ onComplete }) => {
  const N = 1; // 1-back for simplest demo
  const LENGTH = 10;
  const STIMULUS_MS = 700;
  const RESPONSE_MS = 900;

  const [sequence, setSequence] = useState([]);
  const [index, setIndex] = useState(0);
  const [showing, setShowing] = useState(false);
  const [correct, setCorrect] = useState(0);
  const timeoutRef = useRef(null);

  useEffect(() => {
    // generate sequence with some repeats
    const letters = 'ABCDEFGH'.split('');
    const seq = [];
    for (let i = 0; i < LENGTH; i++) {
      if (i >= N && Math.random() < 0.28) {
        seq.push(seq[i - N]);
      } else {
        let s;
        do { s = letters[Math.floor(Math.random() * letters.length)]; } while (i >= N && s === seq[i - N]);
        seq.push(s);
      }
    }
    setSequence(seq);
    setIndex(0);
  }, []);

  useEffect(() => {
    if (!sequence.length) return undefined;
    if (index >= sequence.length) {
      setTimeout(() => onComplete && onComplete(correct >= 2), 250);
      return undefined;
    }

    // show stimulus then allow brief response window
    setShowing(true);
    timeoutRef.current = setTimeout(() => {
      setShowing(false);
      timeoutRef.current = setTimeout(() => setIndex((i) => i + 1), RESPONSE_MS / 2);
    }, STIMULUS_MS);

    return () => clearTimeout(timeoutRef.current);
  }, [index, sequence, onComplete, correct]);

  const handleMatch = () => {
    if (!sequence.length) return;
    const i = index;
    const isMatch = i >= N && sequence[i] === sequence[i - N];
    if (isMatch) setCorrect((c) => c + 1);
    // move to next immediately
    clearTimeout(timeoutRef.current);
    setIndex((i) => Math.min(sequence.length, i + 1));
  };

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'm' || e.code === 'Space') {
        e.preventDefault();
        handleMatch();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [sequence, index]);

  const current = sequence[index] || '-';

  return (
    <div style={{ display: 'grid', gap: 12 }}>
      <div style={{ fontWeight: 800 }}>1-Back (memoria de trabajo) — pulsa 'Match' si coincide con la anterior</div>
      <div style={{ width: 320, height: 160, borderRadius: 10, background: '#fff7ed', display: 'grid', placeItems: 'center', fontSize: 56, boxShadow: '0 8px 20px rgba(2,6,23,0.06)' }}>
        <div style={{ color: showing ? '#111827' : '#9ca3af', fontWeight: 900 }}>{showing ? current : ' '}</div>
      </div>
      <div style={{ display: 'flex', gap: 8, justifyContent: 'center' }}>
        <button className="btn" onClick={handleMatch}>Match (o SPACE)</button>
      </div>
      <div style={{ fontSize: 13, color: '#475569' }}>Progreso: {Math.min(index, sequence.length)} / {sequence.length} — Aciertos: {correct}</div>
    </div>
  );
};

export default DemoNBack;

import React, { useState, useEffect } from 'react';
import { useTelemetry } from '../../TelemetryContext';

// Simplified mirror-angle puzzle: user rotates mirror; if reflected angle aims near target, success

const degToRad = (d) => (d * Math.PI) / 180;

const LaserReflectGame = ({ onComplete }) => {
  const [angle, setAngle] = useState(30);
  const { recordTrialEvent } = useTelemetry();

  useEffect(() => {
    try { recordTrialEvent && recordTrialEvent({ event: 'laser_trial_start', payload: { initialAngle: angle } }); } catch (e) {}
  }, []);

  const checkHit = () => {
    // Mirror located at (150, 100), laser source at (20, 100), target at (330, 60)
    const source = { x: 20, y: 100 };
    const mirror = { x: 150, y: 100 };
    const target = { x: 330, y: 60 };

    const inc = { x: mirror.x - source.x, y: mirror.y - source.y };
    const incLen = Math.hypot(inc.x, inc.y);
    const incNorm = { x: inc.x / incLen, y: inc.y / incLen };

    // mirror normal vector based on angle (mirror angle measured from horizontal)
    const mirrorAngle = degToRad(angle);
    const mirrorNormal = { x: Math.sin(mirrorAngle), y: -Math.cos(mirrorAngle) };

    // reflection r = d - 2*(d·n)*n
    const dot = incNorm.x * mirrorNormal.x + incNorm.y * mirrorNormal.y;
    const rx = incNorm.x - 2 * dot * mirrorNormal.x;
    const ry = incNorm.y - 2 * dot * mirrorNormal.y;

    // direction to target from mirror
    const toTarget = { x: target.x - mirror.x, y: target.y - mirror.y };
    const toTargetLen = Math.hypot(toTarget.x, toTarget.y);
    const toTargetNorm = { x: toTarget.x / toTargetLen, y: toTarget.y / toTargetLen };

    const cos = rx * toTargetNorm.x + ry * toTargetNorm.y;
    const angleDiff = Math.acos(Math.max(-1, Math.min(1, cos))) * (180 / Math.PI);

    return angleDiff < 12; // tolerance 12 degrees
  };

  const computeReflection = (angleVal) => {
    const source = { x: 20, y: 100 };
    const mirror = { x: 150, y: 100 };
    const target = { x: 330, y: 60 };

    const inc = { x: mirror.x - source.x, y: mirror.y - source.y };
    const incLen = Math.hypot(inc.x, inc.y);
    const incNorm = { x: inc.x / incLen, y: inc.y / incLen };

    const mirrorAngle = degToRad(angleVal);
    const mirrorNormal = { x: Math.sin(mirrorAngle), y: -Math.cos(mirrorAngle) };

    const dot = incNorm.x * mirrorNormal.x + incNorm.y * mirrorNormal.y;
    const rx = incNorm.x - 2 * dot * mirrorNormal.x;
    const ry = incNorm.y - 2 * dot * mirrorNormal.y;

    const toTarget = { x: target.x - mirror.x, y: target.y - mirror.y };
    const toTargetLen = Math.hypot(toTarget.x, toTarget.y);
    const toTargetNorm = { x: toTarget.x / toTargetLen, y: toTarget.y / toTargetLen };

    const cos = rx * toTargetNorm.x + ry * toTargetNorm.y;
    const angleDiff = Math.acos(Math.max(-1, Math.min(1, cos))) * (180 / Math.PI);

    return { rx, ry, angleDiff };
  };

  const { rx, ry, angleDiff } = computeReflection(angle);
  const reflectEnd = { x: 150 + rx * 240, y: 100 + ry * 240 };
  const hit = angleDiff < 12;

  return (
    <div>
      <div style={{ marginBottom: 8 }}>Girá el espejo para reflejar el rayo hacia la meta.</div>
      <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <div style={{ width: 360, height: 180, background: '#fff7ed', borderRadius: 8, position: 'relative', border: '1px solid rgba(0,0,0,0.06)' }}>
          <svg width={360} height={180} style={{ position: 'absolute', left: 0, top: 0, pointerEvents: 'none' }} aria-hidden>
            <line x1={20} y1={100} x2={150} y2={100} stroke="#fb923c" strokeWidth={2} />
            <line x1={150} y1={100} x2={reflectEnd.x} y2={reflectEnd.y} stroke={hit ? '#10b981' : '#60a5fa'} strokeWidth={2} strokeDasharray={hit ? '0' : '6 4'} />
            <line x1={150} y1={100} x2={330} y2={60} stroke="#fde68a" strokeWidth={1} strokeDasharray="4 4" />
          </svg>
          <div style={{ position: 'absolute', left: 16, top: 92 }}>🔦</div>
          <div style={{ position: 'absolute', left: 320, top: 52 }}>🎯</div>
          <div style={{ position: 'absolute', left: 140, top: 80, transformOrigin: '10px 10px', transform: `rotate(${angle}deg)` }}>
            <div style={{ width: 80, height: 6, background: '#94a3b8', borderRadius: 3 }} />
            <div style={{ width: 6, height: 6 }} />
          </div>
          <div style={{ position: 'absolute', right: 8, top: 8, fontSize: 12, color: hit ? '#065f46' : '#1e293b' }}>{hit ? 'Acierto probable' : `Desvío ${Math.round(angleDiff)}°`}</div>
        </div>

        <div style={{ display: 'grid', gap: 8 }}>
          <input
            type="range"
            min="-80"
            max="80"
            value={angle}
            onChange={(e) => {
              const v = Number(e.target.value);
              setAngle(v);
              try { recordTrialEvent && recordTrialEvent({ event: 'laser_adjust', payload: { angle: v, tSinceStartMs: Date.now() } }); } catch (e) {}
            }}
          />
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              className="btn"
              onClick={() => {
                const { angleDiff: ad } = computeReflection(angle);
                try { recordTrialEvent && recordTrialEvent({ event: 'laser_try', payload: { angle, angleDiff: ad } }); } catch (e) {}
                if (ad < 12) {
                  try { recordTrialEvent && recordTrialEvent({ event: 'laser_success', payload: { angle, angleDiff: ad } }); } catch (e) {}
                  onComplete && onComplete();
                }
              }}
            >Probar</button>
            <button className="btn" onClick={() => setAngle(30)}>Restablecer</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LaserReflectGame;

import React, { createContext, useContext, useState, useEffect } from 'react';
import '../variants.css';

const VARIANT_KEY = 'ui_variant';
const DEFAULT_VARIANT = import.meta.env.VITE_DEFAULT_UI_VARIANT || 'a';

const VariantContext = createContext({
  variant: DEFAULT_VARIANT,
  setVariant: () => {}
});

export const VariantProvider = ({ children }) => {
  const [variant, setVariantState] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        const saved = localStorage.getItem(VARIANT_KEY);
        if (saved) return saved;
      }
    } catch (e) {
      // ignore
    }
    return DEFAULT_VARIANT;
  });

  useEffect(() => {
    if (typeof document !== 'undefined') {
      document.documentElement.classList.remove('ui-variant-a', 'ui-variant-b', 'ui-variant-c');
      document.documentElement.classList.add(`ui-variant-${variant}`);
    }
    try {
      if (typeof window !== 'undefined') localStorage.setItem(VARIANT_KEY, variant);
    } catch (e) {
      // ignore
    }
  }, [variant]);

  // Decorate panels with collapse toggles when Variant B is active.
  useEffect(() => {
    if (typeof document === 'undefined') return undefined;

    const addCollapses = () => {
      const panels = Array.from(document.querySelectorAll('.lv3-panel'));
      panels.forEach((panel) => {
        if (panel.dataset.vbToggle === '1') return;
        panel.dataset.vbToggle = '1';
        panel.style.position = panel.style.position || 'relative';

        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'variant-collapse-toggle';
        btn.setAttribute('aria-expanded', 'true');
        btn.innerHTML = '<span class="vc-icon">▾</span>';

        btn.addEventListener('click', () => {
          const isCollapsed = panel.classList.toggle('variant-collapsed');
          btn.setAttribute('aria-expanded', String(!isCollapsed));
          const icon = btn.querySelector('.vc-icon');
          if (icon) icon.textContent = isCollapsed ? '▸' : '▾';
        });

        panel.prepend(btn);
      });
    };

    const removeCollapses = () => {
      const panels = Array.from(document.querySelectorAll('.lv3-panel'));
      panels.forEach((panel) => {
        if (panel.dataset.vbToggle !== '1') return;
        const btn = panel.querySelector('.variant-collapse-toggle');
        if (btn) btn.remove();
        panel.classList.remove('variant-collapsed');
        delete panel.dataset.vbToggle;
      });
    };

    if (variant === 'b') {
      // small delay to allow lazy-loaded content to mount
      const t = setTimeout(addCollapses, 120);
      return () => {
        clearTimeout(t);
        removeCollapses();
      };
    }

    // ensure cleanup when leaving variant B
    removeCollapses();
    return undefined;
  }, [variant]);

  const setVariant = (v) => {
    if (!v) return;
    setVariantState(v);
  };

  return (
    <VariantContext.Provider value={{ variant, setVariant }}>
      {children}
    </VariantContext.Provider>
  );
};

export const useVariant = () => useContext(VariantContext);

export default VariantContext;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { playBalloonPump, playBalloonPop, playMemoryFlash } from '../utils/audio';
import Confetti from '../components/Confetti';
import { useTelemetry } from '../TelemetryContext';
import { useLanguage } from '../context/LanguageContext';

const BalloonGame = ({ isActive, onEndGame, isDemo }) => {
  const MAX_ROUNDS = isDemo ? 3 : 10;
  const MIN_PUMPS = 7;
  const { startTracking, stopTracking } = useTelemetry();
  const { language } = useLanguage();

  const [round, setRound] = useState(1);
  const [currentBalloonSize, setCurrentBalloonSize] = useState(1);
  const [currentRoundPoints, setCurrentRoundPoints] = useState(0);
  const [totalPoints, setTotalPoints] = useState(0);
  const [explosionPoint, setExplosionPoint] = useState(0);
  const [gameState, setGameState] = useState('playing'); // playing, exploded, banked
  const [showConfetti, setShowConfetti] = useState(false);

  const totalPointsRef = useRef(0);
  const popsRef = useRef(0);
  const hasEndedRef = useRef(false);

  const initRound = useCallback(() => {
    setCurrentBalloonSize(1);
    setCurrentRoundPoints(0);
    setGameState('playing');
    // explosion threshold between 7 and 18 inclusive
    const MIN_THRESHOLD = 7;
    const MAX_THRESHOLD = 18;
    const threshold = Math.floor(Math.random() * (MAX_THRESHOLD - MIN_THRESHOLD + 1)) + MIN_THRESHOLD;
    setExplosionPoint(threshold);
  }, []);

  const advanceRound = useCallback(() => {
    if (hasEndedRef.current) return;
    
    if (round >= MAX_ROUNDS) {
      hasEndedRef.current = true;
      stopTracking('game4', totalPointsRef.current, popsRef.current, { pops: popsRef.current });
      onEndGame(totalPointsRef.current, popsRef.current);
    } else {
      const next = round + 1;
      setRound(next);
      initRound();
    }
  }, [round, MAX_ROUNDS, onEndGame, initRound, stopTracking]);

  useEffect(() => {
    if (isActive) {
      hasEndedRef.current = false;
      totalPointsRef.current = 0;
      popsRef.current = 0;
      startTracking();
      setRound(1);
      setTotalPoints(0);
      initRound();
    }
  }, [isActive, initRound, startTracking]);

  // Keyboard shortcuts for demo accessibility: Space = pump, Enter = bank
  useEffect(() => {
    const onKeyDown = (e) => {
      if (!isActive || hasEndedRef.current) return;
      // prefer semantic button clicks to reuse existing logic
      const pumpBtn = document.querySelector('.balloon-pump-btn');
      const bankBtn = document.querySelector('.balloon-bank-btn');
      if ((e.code === 'Space' || e.key === ' ') && pumpBtn) {
        e.preventDefault();
        pumpBtn.click();
      }
      if (e.code === 'Enter' && bankBtn) {
        e.preventDefault();
        bankBtn.click();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [isActive]);

  const handlePump = () => {
    if (gameState !== 'playing' || hasEndedRef.current) return;

    const newSize = currentBalloonSize + 1;

    // Disable any chance of an "early" pop until the minimum pump threshold is reached
    const earlyPopChance = currentBalloonSize >= MIN_PUMPS ? Math.min(0.15, currentBalloonSize * 0.02) : 0;
    const isEarlyPop = Math.random() < earlyPopChance;

    if (newSize >= explosionPoint || isEarlyPop) {
      playBalloonPop();
      setGameState('exploded');
      popsRef.current += 1;
      setTimeout(() => advanceRound(), 1500);
    } else {
      playBalloonPump();
      setCurrentBalloonSize(newSize);
      setCurrentRoundPoints(p => p + 10);
    }
  };

  const handleBank = () => {
    if (gameState !== 'playing' || currentBalloonSize === 1 || hasEndedRef.current) return;
    
    totalPointsRef.current += currentRoundPoints;
    setTotalPoints(totalPointsRef.current);
    setGameState('banked');
    try { playMemoryFlash(); } catch (e) {}
    setShowConfetti(true);
    setTimeout(() => setShowConfetti(false), 1200);
    setTimeout(() => advanceRound(), 1500);
  };

  const copy = {
    es: {
      trialLabel: 'RONDA',
      bankTitle: 'BANCO',
      awaiting: 'Esperando la siguiente secuencia...',
      criticalFailure: '[ EXPLOSIÓN ]',
      yieldSecured: 'PUNTOS ASEGURADOS',
      pumpLabel: 'EXPANDIR GLOBO',
      bankBtn: 'ASEGURAR PUNTOS',
      ariaPump: 'Expandir globo (Barra espaciadora)',
      ariaBank: 'Asegurar puntos (Enter)'
    },
    en: {
      trialLabel: 'TRIAL',
      bankTitle: 'BANK',
      awaiting: 'Awaiting next sequence...',
      criticalFailure: '[ CRITICAL FAILURE ]',
      yieldSecured: 'YIELD SECURED',
      pumpLabel: 'PUMP BALLOON',
      bankBtn: 'BANK POINTS',
      ariaPump: 'Pump balloon (Spacebar)',
      ariaBank: 'Bank points (Enter)'
    }
  };

  const t = copy[language] || copy.es;

  if (!isActive) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className="glass-panel"
        style={{ padding: '40px', textAlign: 'center', border: '1px solid #10b981' }}
      >
        <div style={{ color: '#10b981', fontSize: '2rem', marginBottom: '16px' }}>[ STAGE COMPLETE ]</div>
        <p style={{ color: '#64748b', textTransform: 'uppercase', letterSpacing: '2px' }}>Awaiting Next Sequence...</p>
      </motion.div>
    );
  }

  const maxScale = 2.0;
  const rawScale = 1 + (currentBalloonSize * 0.09);
  const visualScale = Math.min(rawScale, maxScale);

  return (
    <div className="flex-center" style={{ width: '100%', minHeight: '520px', display: 'flex', flexDirection: 'column', alignItems: 'center', backgroundColor: 'transparent', fontFamily: '"Courier New", Courier, monospace', position: 'relative', overflow: 'hidden' }}>
      <div style={{ position: 'absolute', top: '30px', left: '40px', fontSize: '1.5rem', color: '#374151', zIndex: 50, background: 'rgba(255,255,255,0.82)', backdropFilter:'blur(8px)', padding: '8px 18px', borderRadius: '8px', border: '1px solid rgba(99,102,241,0.2)', fontWeight:'600' }}>
        {t.trialLabel}: <span style={{color: '#4f46e5', fontWeight: 'bold'}}>{round}</span> / {MAX_ROUNDS}
      </div>
      <div style={{ position: 'absolute', top: '30px', right: '40px', fontSize: '1.5rem', color: '#374151', zIndex: 50, background: 'rgba(255,255,255,0.82)', backdropFilter:'blur(8px)', padding: '8px 18px', borderRadius: '8px', border: '1px solid rgba(99,102,241,0.2)', fontWeight:'600' }}>
        {t.bankTitle}: <span style={{ color: '#059669', fontWeight: 'bold' }}>{totalPoints}</span>
      </div>

      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', position: 'relative' }}>
        <AnimatePresence>
          {gameState === 'playing' && (
            <motion.div
              key="balloon"
              initial={{ scale: 0 }}
              animate={{ scale: visualScale }}
              transition={{ type: 'spring', stiffness: 300, damping: 20 }}
              style={{
                width: '100px',
                height: '100px',
                borderRadius: '50%',
                background: 'radial-gradient(circle at 35% 35%, #6ee7b7 0%, #3b82f6 40%, #1e3a8a 80%)',
                boxShadow: 'inset -15px -15px 30px rgba(0,0,0,0.6), 0 10px 30px rgba(0,0,0,0.4)',
                border: '1px solid rgba(255,255,255,0.2)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: 'white',
                fontWeight: 'bold',
                textShadow: '0 2px 4px rgba(0,0,0,0.5)',
                fontSize: `${1.0 / visualScale}rem` // Keep text readable
              }}
            >
              +{currentRoundPoints}
            </motion.div>
          )}
          
          {gameState === 'exploded' && (
            <motion.div
              key="exploded"
              initial={{ scale: 0.5, opacity: 1 }}
              animate={{ scale: 2, opacity: 0 }}
              transition={{ duration: 0.4 }}
              style={{
                position: 'absolute',
                color: '#ef4444',
                fontSize: '2rem',
                fontWeight: 'bold',
                textShadow: '0 0 20px rgba(239, 68, 68, 0.8)',
                letterSpacing: '4px'
              }}
            >
              [ CRITICAL FAILURE ]
            </motion.div>
          )}

          {gameState === 'banked' && (
            <motion.div
              key="banked"
              initial={{ y: 0, opacity: 0 }}
              animate={{ y: -50, opacity: 1 }}
              exit={{ opacity: 0 }}
              style={{
                position: 'absolute',
                color: '#10b981',
                fontSize: '1.5rem',
                fontWeight: 'bold',
                letterSpacing: '2px'
              }}
            >
              +{currentRoundPoints} YIELD SECURED
            </motion.div>
          )}
        </AnimatePresence>
        {showConfetti && <Confetti count={18} spread={70} duration={1.1} />}
      </div>

        <div style={{ position: 'absolute', bottom: '36px', left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: '24px', zIndex: 200 }}>
        <button
          className="btn balloon-pump-btn"
          aria-label={t.ariaPump}
          onClick={handlePump}
          disabled={gameState !== 'playing'}
          style={{ width: 'auto', minWidth: '160px', padding: '12px 18px', textAlign: 'center', backgroundColor: 'rgba(59, 130, 246, 0.1)', border: '1px solid #3b82f6', color: '#3b82f6', backgroundImage: 'none', boxShadow: gameState === 'playing' ? '0 0 15px rgba(59, 130, 246, 0.2)' : 'none', whiteSpace: 'nowrap' }}
        >
          {t.pumpLabel}
        </button>
        <button
          className="btn balloon-bank-btn"
          aria-label={t.ariaBank}
          onClick={handleBank}
          disabled={gameState !== 'playing' || currentBalloonSize === 1}
          style={{ width: 'auto', minWidth: '160px', padding: '12px 18px', textAlign: 'center', backgroundColor: 'rgba(16, 185, 129, 0.1)', border: '1px solid #10b981', color: '#10b981', backgroundImage: 'none', boxShadow: (gameState === 'playing' && currentBalloonSize > 1) ? '0 0 15px rgba(16, 185, 129, 0.2)' : 'none', whiteSpace: 'nowrap' }}
        >
          {t.bankBtn}
        </button>
      </div>
    </div>
  );
};

export default BalloonGame;

